Translate("deDE", "kingdom-of-stormwind", {
	title = "Königreich Stormwind",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Königreich Stormwind ist das größte Reich der {link:humans}Menschen{/link}, das in den {link:eastern-kingdoms}Östlichen Königreichen{/link} noch steht. Sein Herz ist die weiße Stadt {link:stormwind-city}Stormwind{/link}, und um sie herum liegen die Wälder von {link:elwynn-forest}Elwynn{/link}, die Felder von {link:westfall}Westfall{/link}, {link:razorfen-downs}die Hügel{/link} des {link:redridge-mountains}Rotkammgebirges{/link} und die schattigen Wälder des {link:duskwood}Dämmerwalds{/link}. Zweimal zerbrochen und zweimal wieder aufgebaut, führt es nun die {link:alliance}Allianz{/link} an. Doch sein Thron ist leer, sein Heer ist fern der Heimat, und seine Grenzen sind voller Feinde.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als das Imperium von {link:arathor}Arathor{/link} zu zerfallen begann, verließen die letzten Erben der Blutlinie der {link:arathi-highlands}Arathi{/link} die alte {link:capital-city}Hauptstadt{/link} {link:stromgarde-keep}Strom{/link} und zogen nach Süden. In einem grünen, geschützten Land gründeten sie ein neues Königreich und nannten es {link:azeroth}Azeroth{/link}. Seine Hauptstadt war {link:stormwind-city}Stormwind{/link}. Das Königreich wurde reich und konnte sich selbst versorgen, und viele Jahrhunderte lang hielt es sich aus den Streitigkeiten der nördlichen Reiche heraus. Der Glaube an das {link:holy-light}Heilige Licht{/link} schlug dort tiefe Wurzeln, und die Geistlichen von {link:northshire-abbey}Nordhain{/link} hüteten seine ältesten Bücher.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Erste Krieg.{/b} Die {link:horde}Horde{/link} der {link:orcs}Orcs{/link} kam durch das {link:dark-portal}Dunkle Portal{/link} in die südlichen Sümpfe, und das Königreich {link:azeroth}Azeroth{/link} trug die ganze Last des {link:first-war}Ersten Krieges{/link}. Seine Höfe und Dörfer brannten. Schließlich fiel {link:stormwind-city}Stormwind{/link} selbst, und König {link:llane-wrynn}Llane Wrynn{/link} wurde in seiner eigenen Burg erschlagen. Sir {link:anduin-lothar}Anduin Lothar{/link} führte die Überlebenden über das Meer nach {link:lordaeron}Lordaeron{/link}, unter ihnen den jungen Sohn des Königs, {link:varian-wrynn}Varian{/link}.
• {b}Der Zweite Krieg.{/b} Lothars Warnung bewog König {link:terenas-menethil}Terenas Menethil{/link}, die {link:alliance}Allianz von Lordaeron{/link} zu gründen. Die Verbannten aus Stormwind kämpften im {link:second-war}Zweiten Krieg{/link} an der Seite der nördlichen Königreiche, bis die Horde zerschlagen war.
• {b}Der Wiederaufbau.{/b} Die Verbannten kehrten zu Ruinen heim. Varian wurde zum König gekrönt, und die {link:stonemasons-guild}Steinmetzgilde{/link} errichtete die Stadt aus ihren Trümmern neu. Als das {link:house-of-nobles}Adelshaus{/link} sich weigerte, die Steinmetze zu bezahlen, erfüllten Unruhen die Straßen, und Königin {link:tiffin-wrynn}Tiffin Wrynn{/link} starb im Chaos. Die Steinmetze wurden vertrieben, und aus ihnen ging die {link:defias-brotherhood}Bruderschaft der Defias{/link} hervor.
• {b}Der Dritte Krieg.{/b} Während die Seuche Lordaeron vernichtete, blieb Stormwind vom Schlimmsten des {link:third-war}Dritten Krieges{/link} verschont. Als das nördliche Königreich fiel, wurde Stormwind die erste Macht der Allianz.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:stormwind-city}Stormwind{/link} ist ein Königreich ohne seinen König. {link:varian-wrynn}Varian Wrynn{/link} ist verschwunden, und niemand kann sagen, wohin er gegangen ist. Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link} herrscht als Regent im Namen des jungen Prinzen {link:anduin-wrynn}Anduin Wrynn{/link}. Am Hof hat Lady {link:katrana-prestor}Katrana Prestor{/link} das Ohr der Adligen gewonnen und viel vom Vertrauen des Regenten. Das Heer ist weit von der Heimat fortgezogen, und das Kernland des Königreichs muss von dünnen Garnisonen und Freiwilligen gehalten werden. {link:westfall}Westfall{/link} ist an die {link:defias-brotherhood}Defias{/link} gefallen. {link:riverpaw-gnolls}Gnolle{/link} und {link:kobolds}Kobolde{/link} machen {link:elwynn-forest}Elwynn{/link} unsicher, {link:orcs}Orcs{/link} des Blackrockklans bedrängen das {link:redridge-mountains}Rotkammgebirge{/link}, und im {link:duskwood}Dämmerwald{/link} wandeln die Toten. Agenten von {link:si-7}SI:7{/link} arbeiten im Verborgenen, doch die Nöte des Reiches sind viele und seine Verteidiger wenige.]=],
		},
	},
})

Translate("deDE", "arathor", {
	title = "Arathor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Arathor war die erste Nation der {link:humans}Menschheit{/link}. Es wurde im Krieg gegen die {link:trolls}Trolle{/link} geschmiedet und durch ein Bündnis mit den Elfen gerettet. Aus ihm gingen alle Königreiche der Menschen im Norden wie im Süden hervor. Arathor selbst ist seit mehr als tausend Jahren vergangen, doch seines Blutes und seiner Banner gedenkt man noch überall, wo Menschen herrschen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Fast dreitausend Jahre vor dem Dunklen Portal waren die Stämme der {link:humans}Menschen{/link} im Norden zerstreut und miteinander im Krieg. Die {link:trolls}Trolle{/link} der Amani überfielen sie ohne Gnade. Da beschloss {link:thoradin}Thoradin{/link}, Kriegsherr des Stammes der {link:arathi-highlands}Arathi{/link}, dass die Menschheit sich vereinen oder untergehen müsse. Durch Heirat, durch Versprechen und durch das Schwert brachte er die Stämme unter ein Banner. Er nannte sein Reich Arathor und errichtete seine {link:capital-city}Hauptstadt{/link}, die Festungsstadt {link:stromgarde-keep}Strom{/link}, im Hochland, das noch heute den Namen der Arathi trägt.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Trollkriege.{/b} Als die Amani über {link:quel-thalas}Quel'Thalas{/link} herfielen, sandten die Elfen Boten nach {link:stromgarde-keep}Strom{/link}. Als Gegenleistung für die Schwerter Arathors willigten sie ein, hundert {link:humans}Menschen{/link} die Wege der {link:arcane-magic}Magie{/link} zu lehren. Gemeinsam zerschlugen Elfen und Menschen die Amani am Fuß des Alteracgebirges. Die {link:troll-wars}Trollkriege{/link} endeten, und die Elfen schworen Thoradins Linie dauerhafte Freundschaft.
• {b}Die Ausbreitung.{/b} Nach {link:thoradin}Thoradin{/link} breitete sich das Volk von Arathor weit über Strom hinaus aus. Es gründete {link:dalaran}Dalaran{/link}, die Häfen von {link:gilneas}Gilneas{/link}, das Inselreich {link:kul-tiras}Kul Tiras{/link}, den Bergsitz {link:alterac-mountains}Alterac{/link} und die reichen Lande von {link:lordaeron}Lordaeron{/link}. Jede Stadt wurde stärker, und jede wurde mehr ihr eigener Herr.
• {b}Der Zerfall.{/b} Strom, arm an Land und Handel, verlor langsam seinen Einfluss. Seine großen Familien zogen nach Norden, nach Lordaeron. Die letzten Erben der Linie der {link:arathi-highlands}Arathi{/link} segelten nach Süden und gründeten das Reich, aus dem das {link:kingdom-of-stormwind}Königreich Stormwind{/link} wurde. Strom blieb einigen wenigen herrschenden Häusern überlassen, die es in Stromgarde umbenannten. Aus dem Imperium waren sieben Königreiche geworden.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Arathor lebt nur noch in seinen Erben fort. Die sieben Königreiche wurden einmal wieder vereint, in der {link:alliance}Allianz von Lordaeron{/link}, unter {link:anduin-lothar}Anduin Lothar{/link}, dem letzten von Thoradins Blut. Heute ist das Hochland von {link:stromgarde-keep}Strom{/link} ein Land der Ruinen, um das {link:orcs}Orcs{/link}, {link:trolls}Trolle{/link}, {link:ogres}Oger{/link} und die Räuber des {link:syndicate}Syndikats{/link} kämpfen.]=],
		},
	},
})

Translate("deDE", "lordaeron", {
	title = "Lordaeron",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lordaeron war das mächtigste der Königreiche der {link:humans}Menschen{/link}. Von seiner {link:capital-city}Hauptstadt{/link} in {link:tirisfal-glades}Tirisfal{/link} aus beherrschten seine Könige die nördlichen Lande und führten die {link:alliance}Allianz{/link} an, die die Menschheit im Zweiten Krieg rettete. Es fiel im Dritten Krieg, von innen verraten durch seinen eigenen Prinzen. Seine Lande sind nun das Königreich der Toten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[In den Tagen von {link:arathor}Arathor{/link} nahmen Siedler die fruchtbaren Lichtungen von {link:tirisfal-glades}Tirisfal{/link} in Besitz und benannten das Land nach Lordain, einem General der {link:troll-wars}Trollkriege{/link}. Als {link:stromgarde-keep}Strom{/link} verfiel, verlegten viele seiner Adelsfamilien ihre Güter nach Norden auf diese reichen Felder. Sie machten Lordaeron zu einem eigenen Königreich, und seine Grenzen wuchsen rasch. Lordaeron war auch ein Land des Glaubens. Pilger kamen von weit her zu seinen Klöstern, um Heilung und Weisheit im {link:holy-light}Heiligen Licht{/link} zu suchen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Zweite Krieg.{/b} Als Sir {link:anduin-lothar}Anduin Lothar{/link} die Überlebenden von {link:stormwind-city}Stormwind{/link} nach Norden brachte, nahm König {link:terenas-menethil}Terenas Menethil{/link} sie auf. Dann rief er die Herrscher der Königreiche der {link:humans}Menschen{/link} zusammen und gründete die {link:alliance}Allianz von Lordaeron{/link}. Unter Lothars Befehl trieb sie die {link:horde}Horde{/link} durch das {link:dark-portal}Dunkle Portal{/link} zurück.
• {b}Der unruhige Frieden.{/b} Die besiegten {link:orcs}Orcs{/link} wurden unter großen Kosten in Internierungslagern überall in Lordaeron festgehalten. Die Last spaltete die Allianz. {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} und {link:quel-thalas}Quel'Thalas{/link} verließen sie, und das Königreich von Terenas wurde geschwächt.
• {b}Die Seuche.{/b} Im {link:third-war}Dritten Krieg{/link} verbreitete der {link:cult-of-the-damned}Kult der Verdammten{/link} eine Seuche über das Getreide der nördlichen Lande, und die Toten erhoben sich zu Tausenden. Prinz {link:arthas-menethil}Arthas Menethil{/link} brannte die verseuchte Stadt Stratholme in der {link:culling-of-stratholme}Säuberung{/link} nieder und verfolgte dann die Herren der Seuche bis nach Nordend. Er kehrte als Todesritter der {link:scourge}Geißel{/link} zurück und erschlug seinen Vater auf dessen Thron. Das war der {link:fall-of-lordaeron}Fall von Lordaeron{/link}.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Lordaeron ist ein Königreich der Leichen. Die {link:scourge}Geißel{/link} hält die Pestländer. Unter den Ruinen der {link:capital-city}Hauptstadt{/link} haben die {link:forsaken}Verlassenen{/link} von {link:sylvanas-windrunner}Sylvanas Windrunner{/link} die {link:undercity}Undercity{/link} zu ihrer Heimat gemacht. Der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} verbrennt alle, die er der Seuche verdächtigt, und die {link:argent-dawn}Argentumdämmerung{/link} stellt sich an der Seite aller, die helfen wollen, gegen die Geißel. Kein König der Lebenden herrscht hier mehr.]=],
		},
	},
})

Translate("deDE", "gilneas", {
	title = "Gilneas",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gilneas ist ein stolzes Königreich der {link:humans}Menschen{/link} auf einer zerklüfteten Halbinsel südlich des Silberwalds. Sein Volk ist zäh und selbstständig, und sein Heer gehörte einst zu den stärksten der sieben Königreiche. Nach dem Zweiten Krieg schloss sein König das Reich hinter einer großen Mauer von der Welt ab. Was hinter dieser Mauer geschieht, kann kein Außenstehender sagen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Gilneas war einer der Stadtstaaten, die das Volk von {link:arathor}Arathor{/link} nach den Trollkriegen gründete. Seine Siedler bauten starke Häfen entlang der Küste, und seine kühnsten Seeleute gründeten später {link:kul-tiras}Kul Tiras{/link}. Da Gilneas mit der Flotte von Kul Tiras nicht mithalten konnte, wandte es sich dem Handel und den Waffen zu. Seine Soldaten galten als jedem anderen in Arathor ebenbürtig.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Zweite Krieg.{/b} {link:genn-greymane}König Genn Greymane{/link} trat der Allianz von Lordaeron ohne große Zuneigung bei. Er glaubte, dass Gilneas sich allein verteidigen könne, und hielt seine Heere nahe der Heimat.
• {b}{link:the-greymane-wall}Der Greymane-Wall{/link}.{/b} Nach dem Krieg erzürnten ihn die Kosten der {link:internment-camps}Internierungslager{/link} der {link:orcs}Orcs{/link}. Greymane zog Gilneas aus der {link:alliance}Allianz{/link} zurück. Dann errichtete er eine gewaltige Mauer quer über die Nordgrenze seines Königreichs und schloss ihre Tore. Die Mauer durchschnitt die Lande seiner eigenen Adligen und ließ Dörfer wie {link:pyrewood-village}Pyrewood{/link} und {link:ambermill}Ambermill{/link} draußen.
• {b}Der Dritte Krieg.{/b} Als die Seuche über {link:lordaeron}Lordaeron{/link} hinwegfegte, blieben die Tore von Gilneas geschlossen. Kein Heer kam aus dem Süden, um dem sterbenden Königreich zu helfen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:the-greymane-wall}Der Greymane-Wall{/link} steht noch, und seine Tore sind noch geschlossen. Jenseits davon, im {link:silverpine-forest}Silberwald{/link}, ringen die {link:scourge}Geißel{/link} und die {link:forsaken}Verlassenen{/link} um die alten Lande des Nordens. Die Dorfbewohner außerhalb der Mauer müssen allein für sich sorgen. Was aus dem Königreich dahinter geworden ist, ist nicht bekannt.]=],
		},
	},
})

Translate("deDE", "kul-tiras", {
	title = "Kul Tiras",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kul Tiras ist ein Inselkönigreich im Großen Meer, westlich von Khaz Modan. Es ist eine Nation von Seeleuten und Schiffsbauern, und seine Flotte war einst die größte der Welt. Aus dem Haus Proudmoore kamen seine Admirale, und aus seinen Häfen kamen die Flotten, die die {link:alliance}Allianz{/link} in den Krieg trugen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Seeleute aus {link:gilneas}Gilneas{/link} entdeckten im Süden eine große Insel, reich an Erz und Holz. Einige von ihnen blieben und gründeten dort einen Seeposten, der zu einem eigenen Königreich heranwuchs. Kul Tiras gedieh durch Fischfang und Handel. Seine Handelsflotten befuhren jede Küste der bekannten Welt, und in den Tagen von {link:arathor}Arathor{/link} besaß es die größte Flotte des Imperiums.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Zweite Krieg.{/b} Großadmiral {link:daelin-proudmoore}Daelin Proudmoore{/link} brachte die Flotten von Kul Tiras in die {link:alliance}Allianz von Lordaeron{/link}. Seine Schiffe bekämpften die Flotten der {link:orcs}Orcs{/link} auf den Meeren und hielten die Heere der Allianz versorgt. Das Königreich zahlte einen hohen Preis an Schiffen und Männern.
• {b}Der unruhige Frieden.{/b} Als die Allianz nach dem Krieg schwächer wurde, blieb Kul Tiras ihr treu, zog sich aber mehr und mehr in die eigenen Angelegenheiten zurück.
• {b}{link:theramore-isle}Theramore{/link}.{/b} Nach dem {link:third-war}Dritten Krieg{/link} führte Daelins Tochter {link:jaina-proudmoore}Jaina Proudmoore{/link} die Überlebenden des Nordens nach {link:kalimdor}Kalimdor{/link}, wo sie mit den Orcs von {link:thrall}Thrall{/link} Frieden schloss. Daelin wollte das nicht hinnehmen. Er kam mit seiner Flotte, um die {link:horde}Horde{/link} zu vernichten, und fiel im Kampf vor den Mauern von Theramore.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Kul Tiras liegt fern jenseits des Meeres und nimmt an den Angelegenheiten des Festlands wenig Anteil. An den Küsten Kalimdors halten Marinesoldaten aus Kul Tiras noch die Feste {link:northwatch-hold}Northwatch{/link} im {link:the-barrens}Brachland{/link} und {link:tiragarde-keep}Burg Tiragarde{/link} in {link:durotar}Durotar{/link}. Sie haben der {link:horde}Horde{/link} den Tod ihres Admirals nicht verziehen.]=],
		},
	},
})

Translate("deDE", "dalaran", {
	title = "Dalaran",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dalaran ist {link:city-of-dalaran}die Stadt der Magier{/link}. Es war der erste Stadtstaat von {link:arathor}Arathor{/link}, der sich selbst regierte, und mehr als zweitausend Jahre lang war es das Herz der Magie der {link:humans}Menschen{/link}. Seine violetten Türme erhoben sich über den Ufern des Lordameresees, bis die {link:scourge}Geißel{/link} und die {link:burning-legion}Brennende Legion{/link} sie niederwarfen. Nun hat sich Dalaran im {link:alterac-mountains}Alteracgebirge{/link} wieder erhoben, und seine Magier sind seine Herren.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Dalaran begann als Handelsposten inmitten von {link:arathor}Arathor{/link}. Es wuchs rasch und wurde eine Zuflucht für die Magier des Imperiums, denen das einfache Volk misstraute. Unter dem Magier Ardogan errang die Stadt ihre Freiheit von {link:stromgarde-keep}Strom{/link} und wurde von Zauberern regiert. Ihre leichtsinnige Magie zog die Aufmerksamkeit von Dämonen auf sich. Um diese im Geheimen zu bekämpfen, gründeten die Magier von Dalaran und die Elfen von {link:quel-thalas}Quel'Thalas{/link} den Rat von {link:tirisfal-glades}Tirisfal{/link}, dessen {link:the-night-watch}Wächter{/link} die Welt über Generationen verteidigten. Mit der Zeit bildeten die Magier der Stadt die {link:kirin-tor}Kirin Tor{/link}, die schließlich über sie herrschten.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Zweite Krieg.{/b} Dalaran trat der {link:alliance}Allianz von Lordaeron{/link} bei und sandte seine Magier in den Kampf gegen die {link:orcs}Orcs{/link}. Nach dem Krieg bewachten seine Zauberer das Dunkle Portal von {link:nethergarde-keep}Burg Nethergarde{/link} aus.
• {b}Der Dritte Krieg.{/b} Der Nekromant {link:kel-thuzad}Kel'Thuzad{/link}, einst ein Magier Dalarans, gründete den {link:cult-of-the-damned}Kult der Verdammten{/link}. Auf sein Geheiß führte {link:arthas-menethil}Arthas Menethil{/link} die {link:scourge}Geißel{/link} gegen die Stadt und erbeutete das Zauberbuch von {link:medivh}Medivh{/link}. Damit wurde {link:archimonde}Archimonde{/link} in die Welt beschworen. Der Dämonenfürst zerschmetterte Dalaran mit einem einzigen Zauber und ließ es in Ruinen zurück.
• {b}Der Wiederaufbau.{/b} Die überlebenden Magier kehrten zu den Ruinen zurück. Sie errichteten eine große violette Barriere über der Stadt und bauten sie hinter diesem Schild wieder auf, verborgen vor der Welt.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Dalaran steht wieder aufgebaut im {link:alterac-mountains}Alteracgebirge{/link}, und seine Barriere ist verschwunden. Niemand außerhalb der {link:kirin-tor}Kirin Tor{/link} kann bisher sagen, warum sie fiel. Die Stadt ist wieder offen, und ihre Straßen sind voller Magier, Händler und Bankiers. Doch im Inneren ist nicht alles in Ordnung. Verzauberungen misslingen, arkane Konstrukte laufen Amok, und dämonische Energie regt sich in den Straßen. Die Kirin Tor sind stolz, und sie geben nicht gern zu, dass sie Hilfe brauchen.]=],
		},
	},
})

Translate("deDE", "kirin-tor", {
	title = "Kirin Tor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kirin Tor sind die Magier von {link:dalaran}Dalaran{/link} und die Herrscher dieser Stadt. Sie sind die Hüter der Magie der {link:humans}Menschen{/link}: ihre Gelehrten, ihre Richter und ihre {link:the-night-watch}Wächter{/link}. Seit Langem beanspruchen sie das Recht, über jeden Zauber zu wachen, der in den Landen der Menschen gewirkt wird, und sie hüten ihre Geheimnisse eifersüchtig.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als das Imperium von {link:arathor}Arathor{/link} zu zerbrechen begann, bildeten die Magier von {link:dalaran}Dalaran{/link} eine Gemeinschaft, um jeden Zauber und jedes magische Relikt, das der Menschheit bekannt war, zu studieren und aufzuzeichnen. Diese Gemeinschaft waren die Kirin Tor. Sie wuchs zum herrschenden Orden der Stadt heran, geführt von einem Rat ihrer größten Mitglieder. Von ihrer Violetten Zitadelle aus urteilten sie, welche Magie ausgeübt werden durfte und welche verboten werden musste.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die {link:the-night-watch}Wächter{/link}.{/b} Jahrhundertelang arbeiteten die Kirin Tor mit dem Rat von {link:tirisfal-glades}Tirisfal{/link} zusammen, der die Wächter erwählte, die im Geheimen gegen Dämonen kämpften. Der letzte Wächter war {link:medivh}Medivh{/link}.
• {b}Der Zweite Krieg.{/b} Die Magier der Kirin Tor kämpften für die {link:alliance}Allianz von Lordaeron{/link}. Nach dem Krieg errichteten sie {link:nethergarde-keep}Burg Nethergarde{/link} nahe dem {link:dark-portal}Dunklen Portal{/link}, um das verwüstete Land dahinter zu beobachten.
• {b}Der Dritte Krieg.{/b} Die Kirin Tor hatten den Magier {link:kel-thuzad}Kel'Thuzad{/link} wegen seiner Studien der Nekromantie ausgestoßen. Er kehrte als Meister des {link:cult-of-the-damned}Kults der Verdammten{/link} zurück, und seine Seuche vernichtete {link:lordaeron}Lordaeron{/link}. Erzmagier Antonidas, das Oberhaupt des Ordens, wurde erschlagen, als die {link:scourge}Geißel{/link} {link:dalaran}Dalaran{/link} einnahm.
• {b}Die Worgen.{/b} Ein Magier des Ordens, {link:archmage-arugal}Erzmagier Arugal{/link}, beschwor die wilden Worgen, um im {link:silverpine-forest}Silberwald{/link} gegen die Geißel zu kämpfen. Sie erwiesen sich als ebenso großer Fluch wie die Untoten. Arugal hält nun {link:shadowfang-keep}Burg Shadowfang{/link}, und man sagt, er habe den Verstand verloren.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Kirin Tor haben {link:dalaran}Dalaran{/link} im {link:alterac-mountains}Alteracgebirge{/link} wieder aufgebaut, und seine Barriere ist gefallen. In der Stadt schlagen ihre Zauber fehl und ihre Konstrukte reißen sich los, und sie mühen sich, die Kontrolle über ihre eigenen Straßen zu behalten. Ihre Magier halten noch immer Wache in {link:nethergarde-keep}Nethergarde{/link}, und einige von ihnen stehen in {link:theramore-isle}Theramore{/link} an der Seite von {link:jaina-proudmoore}Jaina Proudmoore{/link}.]=],
		},
	},
})

Translate("deDE", "quel-thalas", {
	title = "Quel'Thalas",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Quel'Thalas ist das Königreich der {link:high-elves}Hochelfen{/link} in den nördlichen Wäldern von {link:lordaeron}Lordaeron{/link}. Tausende Jahre lang war es ein Reich des ewigen Frühlings, genährt von der Magie des Sonnenbrunnens. Im {link:third-war}Dritten Krieg{/link} marschierte die {link:scourge}Geißel{/link} durch seine Tore und schändete seine heilige Quelle. Was vom Königreich bleibt, liegt still und fern.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nach der {link:great-sundering}Großen Teilung{/link} verließ eine Schar verbannter Hochgeborener {link:kalimdor}Kalimdor{/link}, von den {link:night-elves}Nachtelfen{/link} ihrer Liebe zur Magie wegen verstoßen. Angeführt von Dath'Remar Sunstrider überquerten sie das Meer und ließen sich im Norden der {link:eastern-kingdoms}Östlichen Königreiche{/link} nieder. Dort gründeten sie Quel'Thalas und errichteten den Sonnenbrunnen, eine Quelle arkaner Macht. Runensteine wurden in den Wäldern aufgestellt, um ihre Magie vor den Dämonen zu verbergen, die sie anlocken könnte.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die {link:troll-wars}Trollkriege{/link}.{/b} Die {link:trolls}Trolle{/link} der Amani hätten das junge Königreich beinahe überrannt. Die Elfen suchten Hilfe bei {link:arathor}Arathor{/link} und lehrten hundert {link:humans}Menschen{/link} die Magie im Austausch für dessen Heere. Gemeinsam zerschlugen sie die Amani, und die Elfen schworen der Linie Thoradins Freundschaft.
• {b}Der Zweite Krieg.{/b} Als die {link:horde}Horde{/link} und die Amani die Wälder in Brand setzten, löste König Anasterian Sunstrider seine alte Schuld ein und trat der {link:alliance}Allianz von Lordaeron{/link} bei. Nach dem Krieg befand er, dass die Allianz sein Volk im Stich gelassen hatte, und er trat aus ihr aus.
• {b}Der Dritte Krieg.{/b} Prinz {link:arthas-menethil}Arthas Menethil{/link} führte die {link:scourge}Geißel{/link} nach Norden. Waldläufergeneralin {link:sylvanas-windrunner}Sylvanas Windrunner{/link} bekämpfte ihn an jedem Tor und wurde erschlagen. Arthas tötete König Anasterian und nutzte den Sonnenbrunnen, um {link:kel-thuzad}Kel'Thuzad{/link} als Lich zu erwecken. Das Herz des Elfenreichs war geschändet.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Quel'Thalas liegt jenseits der Pestländer, durch die {link:scourge}Geißel{/link} vom Süden abgeschnitten. Nur wenige Nachrichten kommen von dort. Die {link:high-elves}Hochelfen{/link}, die in den südlichen Landen geblieben sind, leben in kleinen, verstreuten Gruppen, wie die Waldläufer der {link:quel-danil-lodge}Quel'Danil-Hütte{/link} im {link:the-hinterlands}Hinterland{/link}. Viele von ihnen trauern um eine Heimat, die sie vielleicht nie wiedersehen.]=],
		},
	},
})

Translate("deDE", "alliance", {
	title = "Allianz",
	aliases = { "Allianz von Lordaeron" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Allianz ist der Bund der Völker, die sich gegen ihre gemeinsamen Feinde zusammengeschlossen haben. {link:humans}Menschen{/link}, {link:dwarves}Zwerge{/link}, {link:gnomes}Gnome{/link} und {link:night-elves}Nachtelfen{/link} gehören ihr an. Sie wurde im Zweiten Krieg geboren, um sich der {link:horde}Horde{/link} der {link:orcs}Orcs{/link} zu stellen, und sie ist seither zerbrochen und neu geformt worden. Heute sind ihre größten Mächte das {link:kingdom-of-stormwind}Königreich Stormwind{/link} und das {link:kingdom-of-ironforge}Königreich Ironforge{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als {link:stormwind-city}Stormwind{/link} im {link:first-war}Ersten Krieg{/link} fiel, brachte Sir {link:anduin-lothar}Anduin Lothar{/link} seine Überlebenden nach {link:lordaeron}Lordaeron{/link} und warnte, dass die {link:horde}Horde{/link} nach Norden kommen würde. König {link:terenas-menethil}Terenas Menethil{/link} hörte auf ihn. Er rief die Herrscher der Königreiche der {link:humans}Menschen{/link} zusammen und band sie in der Allianz von Lordaeron, mit Lothar als ihrem obersten Befehlshaber. Auch die {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link}, die {link:gnomes}Gnome{/link} von {link:gnomeregan}Gnomeregan{/link} und die {link:high-elves}Hochelfen{/link} von {link:quel-thalas}Quel'Thalas{/link} traten ihr bei.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Zweite Krieg.{/b} Die Allianz trat der {link:horde}Horde{/link} überall im Norden entgegen und drängte sie bis zur Blackrockspitze zurück. {link:anduin-lothar}Lothar{/link} fiel in den letzten Schlachten, und sein Leutnant {link:turalyon}Turalyon{/link} führte den endgültigen Sieg herbei. Die überlebenden {link:orcs}Orcs{/link} wurden in {link:internment-camps}Internierungslager{/link} getrieben.
• {b}Der Bruch.{/b} Die Kosten der Lager und alter Groll spalteten die Allianz. {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} und {link:quel-thalas}Quel'Thalas{/link} verließen sie. {link:alterac-mountains}Alterac{/link} hatte sie bereits an die Horde verraten und seine Krone verloren.
• {b}Der Dritte Krieg.{/b} Die Seuche und die {link:scourge}Geißel{/link} vernichteten {link:lordaeron}Lordaeron{/link}. {link:jaina-proudmoore}Jaina Proudmoore{/link} führte Überlebende nach Westen, nach {link:kalimdor}Kalimdor{/link}, wo {link:humans}Menschen{/link}, Orcs und {link:night-elves}Nachtelfen{/link} in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} Seite an Seite kämpften.
• {b}Die neue Allianz.{/b} In den Jahren seither hat {link:stormwind-city}Stormwind{/link} das Banner aufgenommen, das Lordaeron fallen ließ. {link:ironforge}Ironforge{/link} steht an seiner Seite, die {link:gnomes}Gnome{/link} des gefallenen {link:gnomeregan}Gnomeregan{/link} finden Zuflucht bei den Zwergen, und die Nachtelfen von {link:darnassus}Darnassus{/link} sind ihr beigetreten.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Allianz ist auf dem Papier stark und in Wahrheit überdehnt. König {link:varian-wrynn}Varian Wrynn{/link} ist verschwunden, und Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link} regiert {link:stormwind-city}Stormwind{/link} als Regent. König {link:magni-bronzebeard}Magni Bronzebeard{/link} herrscht über {link:ironforge}Ironforge{/link}. {link:tyrande-whisperwind}Tyrande Whisperwind{/link} führt die {link:night-elves}Nachtelfen{/link}, und {link:jaina-proudmoore}Jaina Proudmoore{/link} hält {link:theramore-isle}Theramore{/link}. Ihre Soldaten bekämpfen die {link:horde}Horde{/link} im {link:ashenvale}Eschental{/link} und im {link:the-barrens}Brachland{/link}, die {link:scourge}Geißel{/link} in {link:lordaeron}Lordaeron{/link} und ein Dutzend kleinerer Feinde in der Heimat. Vom Frieden mit den {link:orcs}Orcs{/link} wird oft gesprochen, und selten wird ihm getraut.]=],
		},
	},
})

Translate("deDE", "horde", {
	title = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Horde ist der Bund der {link:orcs}Orcs{/link} und ihrer Verbündeten: der {link:darkspear-trolls}Trolle der Darkspear{/link}, der {link:tauren}Tauren{/link} und der {link:forsaken}Verlassenen{/link}. Sie wurde auf einer anderen Welt als Werkzeug von Dämonen geboren. Sie kam nach {link:azeroth}Azeroth{/link}, brannte Königreiche nieder und wurde zerschlagen. Dann wurde sie unter einem jungen Kriegshäuptling als ein Volk wiedergeboren, das nach Freiheit sucht. Ihre {link:capital-city}Hauptstadt{/link} ist {link:orgrimmar}Orgrimmar{/link} im roten Land {link:durotar}Durotar{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Auf der Welt Draenor waren die {link:orcs}Orcs{/link} ein stolzes Volk aus Clans und Schamanen. Der Dämon {link:kil-jaeden}Kil'jaeden{/link} von der {link:burning-legion}Brennenden Legion{/link} machte sich daran, sie zu seiner Waffe zu machen. Durch den Schamanen {link:ner-zhul}Ner'zhul{/link} und dann den Hexenmeister {link:gul-dan}Gul'dan{/link} lehrte er sie die {link:fel-magic}Teufelsmagie{/link}. Schließlich tranken die Häuptlinge der Clans das Blut des Dämons {link:mannoroth}Mannoroth{/link}, und ein brennender Blutdurst band sie an die Legion. Vereint als eine Horde vernichteten sie die Draenei, und ihre Welt verdorrte unter ihnen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Erste Krieg.{/b} Durch das {link:dark-portal}Dunkle Portal{/link} fiel die Horde in das Königreich {link:azeroth}Azeroth{/link} ein und zerstörte es. {link:stormwind-city}Stormwind{/link} fiel, und König {link:llane-wrynn}Llane Wrynn{/link} wurde erschlagen.
• {b}Der Zweite Krieg.{/b} Unter Kriegshäuptling {link:orgrim-doomhammer}Orgrim Doomhammer{/link} marschierte die Horde mit Ogern, Trollen der Amani, Goblins und versklavten roten Drachen nach Norden. Die {link:alliance}Allianz{/link} besiegte sie, und die meisten überlebenden {link:orcs}Orcs{/link} wurden in {link:internment-camps}Internierungslager{/link} gesperrt.
• {b}Die neue Horde.{/b} In den {link:camping}Lagern{/link} versanken die Orcs in einer seltsamen Lethargie. Ein junger Orc, der als Sklave aufgewachsen war, {link:thrall}Thrall{/link}, befreite sich, erlernte die alten Wege der Schamanen und befreite sein Volk. Doomhammer starb an seiner Seite im Kampf und übergab ihm seinen Hammer und seinen Titel.
• {b}Der Dritte Krieg.{/b} Dem Propheten {link:medivh}Medivh{/link} folgend, führte Thrall die Horde nach {link:kalimdor}Kalimdor{/link}. Dort gewann er die Freundschaft der {link:darkspear-trolls}Darkspear{/link} und der {link:tauren}Tauren{/link} von {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. {link:grom-hellscream}Grom Hellscream{/link} erschlug {link:mannoroth}Mannoroth{/link} und befreite die Orcs von seinem Blutfluch. Die Horde kämpfte an der Seite der Allianz in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link}.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:thrall}Thrall{/link} herrscht als Kriegshäuptling von {link:orgrimmar}Orgrimmar{/link} aus, das zu Ehren Doomhammers benannt ist. {link:cairne-bloodhoof}Cairne{/link} führt die {link:tauren}Tauren{/link} von {link:thunder-bluff}Thunder Bluff{/link} aus, {link:vol-jin}Vol'jin{/link} führt die {link:darkspear-trolls}Darkspear{/link}, und {link:sylvanas-windrunner}Sylvanas Windrunner{/link} bringt die Verlassenen von {link:lordaeron}Lordaeron{/link} an die Seite der Horde. Der Frieden mit {link:theramore-isle}Theramore{/link} hält, aber nur knapp. Im {link:ashenvale}Eschental{/link} schlagen {link:orcs}Orcs{/link} Holz in den Wäldern der {link:night-elves}Nachtelfen{/link}, und dafür wird Blut vergossen. Marinesoldaten aus {link:kul-tiras}Kul Tiras{/link} bewachen die Küsten, {link:centaurs}Zentauren{/link} und {link:quilboar}Stacheleber{/link} bedrängen jede Grenze, und der Dämonenkult der {link:burning-blade}Brennenden Klinge{/link} schwärt mitten in {link:durotar}Durotar{/link} selbst.]=],
		},
	},
})

Translate("deDE", "burning-legion", {
	title = "Brennende Legion",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Brennende Legion ist ein gewaltiges Heer von Dämonen, das unzählige Welten verwüstet hat. Ihr Herr ist {link:sargeras}Sargeras{/link}, ein gefallener Titan, der einst die Schöpfung verteidigte und sie nun zunichtemachen will. Dreimal hat die Legion nach {link:azeroth}Azeroth{/link} gegriffen. Dreimal wurde sie zurückgeschlagen, zu einem schrecklichen Preis.]=],
		},
		{
			title = "Ursprünge",
			text = [=[{link:sargeras}Sargeras{/link} war einst der größte Vorkämpfer der Titanen, der Erschaffer der Welten. In Zeitaltern des Krieges gegen die Dämonen des Wirbelnden Nethers gelangte er zu der Überzeugung, dass die ganze Schöpfung fehlerhaft sei und verbrannt werden müsse. Er wandte sich gegen seinesgleichen und sammelte ein Heer von Dämonen, um dies zu tun. Zu den Ersten, die er verdarb, gehörten die Eredar, deren Anführer {link:kil-jaeden}Kil'jaeden{/link} und {link:archimonde}Archimonde{/link} seine obersten Leutnants wurden.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Krieg der Ahnen.{/b} {link:queen-azshara}Königin Azshara{/link} und ihre Hochgeborenen holten die Legion durch den {link:well-of-eternity}Brunnen der Ewigkeit{/link} in die Welt. Die {link:night-elves}Nachtelfen{/link}, angeführt von {link:malfurion-stormrage}Malfurion Stormrage{/link}, wehrten sich im {link:war-of-the-ancients}Krieg der Ahnen{/link}. Die Zerstörung des Brunnens zerschmetterte den Kontinent in der {link:great-sundering}Großen Teilung{/link} und schnitt die Dämonen ab.
• {b}Die Horde.{/b} {link:kil-jaeden}Kil'jaeden{/link} verdarb daraufhin die {link:orcs}Orcs{/link} von Draenor und machte sie zu einer Waffe. Die {link:horde}Horde{/link}, die er schmiedete, wurde im {link:first-war}Ersten Krieg{/link} und im {link:second-war}Zweiten Krieg{/link} gegen {link:azeroth}Azeroth{/link} geschleudert.
• {b}Der Dritte Krieg.{/b} Die Legion schuf die {link:scourge}Geißel{/link}, um den Weg zu bereiten. Die Seuche tötete {link:lordaeron}Lordaeron{/link}, und {link:archimonde}Archimonde{/link} selbst wurde in {link:dalaran}Dalaran{/link} in die Welt beschworen. Er marschierte gegen den Weltbaum {link:nordrassil}Nordrassil{/link}. In der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} hielten ihn Nachtelfen, {link:humans}Menschen{/link} und Orcs lange genug auf, damit die Geister der Ahnen ihn vernichten konnten.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:archimonde}Archimonde{/link} ist tot, doch die Legion ist nicht aus {link:azeroth}Azeroth{/link} verschwunden. Dämonen spuken noch in den verderbten Wäldern des {link:felwood}Teufelswalds{/link}, den Ruinen von {link:azshara}Azshara{/link} und den Öden von {link:desolace}Desolace{/link}. Der Kult der {link:burning-blade}Brennenden Klinge{/link} dient ihnen im Geheimen unter den {link:orcs}Orcs{/link}. In den {link:blasted-lands}Verwüsteten Landen{/link} beobachten die Magier von {link:nethergarde-keep}Nethergarde{/link} das {link:dark-portal}Dunkle Portal{/link} auf jedes Zeichen ihrer Rückkehr.]=],
		},
	},
})

Translate("deDE", "scourge", {
	title = "Geißel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Geißel ist ein Heer der Untoten, erweckt durch die Seuche und beherrscht vom Lichkönig im Eis von Nordend. Im {link:third-war}Dritten Krieg{/link} vernichtete sie das Königreich {link:lordaeron}Lordaeron{/link}, schändete {link:quel-thalas}Quel'Thalas{/link} und machte {link:dalaran}Dalaran{/link} dem Erdboden gleich. Sie hält noch immer weite Teile des Nordens, und noch immer hungert sie nach den Lebenden.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nachdem die {link:orcs}Orcs{/link} ihn enttäuscht hatten, bestrafte {link:kil-jaeden}Kil'jaeden{/link} von der {link:burning-legion}Brennenden Legion{/link} ihren alten Schamanen {link:ner-zhul}Ner'zhul{/link}. Er riss dem Orc den Körper fort und band seinen Geist in eine Rüstung, die in einem Eisblock versiegelt war. Dann warf er ihn nach Nordend und nannte ihn den Lichkönig. Seine Aufgabe war es, eine Seuche des Untodes über die Lande der {link:humans}Menschen{/link} zu verbreiten und sie für die Legion vorzubereiten. Von seinem Frostthron aus griff der Lichkönig mit seinem Geist nach den Lebenden, und er zog die Ehrgeizigen und die Verzweifelten auf seine Seite.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Seuche.{/b} Der Magier {link:kel-thuzad}Kel'Thuzad{/link} hörte den Ruf des Lichkönigs und gründete den {link:cult-of-the-damned}Kult der Verdammten{/link}. Durch den Kult wurde die Seuche im Getreide des nördlichen {link:lordaeron}Lordaeron{/link} verbreitet. Wer davon aß, starb und erhob sich wieder als Untoter.
• {b}Der Fall.{/b} Prinz {link:arthas-menethil}Arthas Menethil{/link} jagte der Seuche bis nach Nordend nach. Dort ergriff er die Runenklinge Frostgram und wurde der Champion des Lichkönigs. Er kehrte zurück, um seinen Vater zu ermorden und Lordaeron den Toten auszuliefern. Dann führte er die Geißel durch {link:quel-thalas}Quel'Thalas{/link}, wo er Kel'Thuzad als Lich erweckte, und weiter nach {link:dalaran}Dalaran{/link}, wo der Dämonenfürst {link:archimonde}Archimonde{/link} beschworen wurde.
• {b}Das Zerbrechen der Ketten.{/b} Nachdem Archimonde am {link:mount-hyjal}Berg Hyjal{/link} gefallen war, ließ der Griff des Lichkönigs nach. Viele der Untoten befreiten sich, und {link:sylvanas-windrunner}Sylvanas Windrunner{/link} führte sie als die {link:forsaken}Verlassenen{/link}. Arthas zog nach Norden, um dem Lichkönig beizustehen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Geißel herrscht noch über die Pestländer. {link:kel-thuzad}Kel'Thuzad{/link} befiehlt im Namen des Lichkönigs, und seine Diener halten die zerstörte Stadt Stratholme, die Schule der Nekromantie in Scholomance und so manchen gefallenen Ort. Verseuchte Kreaturen streifen durch die Wälder, und Monstrositäten bewachen die toten Lande. Gegen sie stehen die Verlassenen, der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} und die {link:argent-dawn}Argentumdämmerung{/link}, die sich sonst in nichts einig sind.]=],
		},
	},
})

Translate("deDE", "cult-of-the-damned", {
	title = "Kult der Verdammten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kult der Verdammten ist die lebende Priesterschaft der {link:scourge}Geißel{/link}. Seine Mitglieder verehren den Lichkönig und dienen ihm bereitwillig, in der Hoffnung auf ewiges Leben nach dem Tod. Es war der Kult, der die Seuche nach {link:lordaeron}Lordaeron{/link} trug, und seine Nekromanten erwecken noch immer die Toten im Namen des Lichkönigs.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Der Kult wurde von {link:kel-thuzad}Kel'Thuzad{/link} gegründet, einem Magier der {link:kirin-tor}Kirin Tor{/link}, der wegen seiner verbotenen Studien der Nekromantie ausgestoßen worden war. Er reiste nach Nordend und hörte die Stimme des Lichkönigs. Er kehrte als dessen Prophet nach {link:lordaeron}Lordaeron{/link} zurück. Unter den Armen und Vergessenen des Nordens predigte er eine neue Gesellschaft, in der alle gleich wären und der Tod kein Ende wäre. Tausende folgten ihm, und nur wenige verstanden, wem sie sich angeschlossen hatten.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Seuche.{/b} Der Kult verbreitete eine Seuche des Untodes durch die Kornspeicher des nördlichen {link:lordaeron}Lordaeron{/link}. Von {link:ruins-of-andorhal}Andorhal{/link} ging verseuchtes Getreide in die Dörfer hinaus, und die Toten begannen sich zu erheben.
• {b}Kel'Thuzads Tod und Rückkehr.{/b} Prinz {link:arthas-menethil}Arthas Menethil{/link} erschlug {link:kel-thuzad}Kel'Thuzad{/link} in Andorhal. Nachdem Arthas in den Dienst des Lichkönigs gefallen war, trug er die Überreste des Nekromanten zum Sonnenbrunnen von {link:quel-thalas}Quel'Thalas{/link} und erweckte ihn als Lich.
• {b}Scholomance.{/b} Die Familie Barov überließ dem Kult ihre Inselburg {link:caer-darrow}Caer Darrow{/link}. Dort, in der Scholomance, bildet der Kult neue Nekromanten aus.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Kult ist in den Pestländern noch stark. Seine Akolythen dienen in den Ruinen von Stratholme und {link:ruins-of-andorhal}Andorhal{/link}. In der Scholomance lehrt Dunkelmeister Gandling willige Schüler die Nekromantie. Die Agenten des Kults bewegen sich noch immer unter den Lebenden, auf der Suche nach neuen Anhängern und neuen Wegen, die Seuche zu verbreiten.]=],
		},
	},
})

Translate("deDE", "scarlet-crusade", {
	title = "Scharlachroter Kreuzzug",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Scharlachrote Kreuzzug ist ein streitbarer Orden des {link:holy-light}Heiligen Lichts{/link}, der geschworen hat, die Untoten von {link:lordaeron}Lordaeron{/link} zu vernichten. Er wurde aus dem Schmerz des Dritten Krieges geboren und ist hart und fanatisch geworden. Der Kreuzzug traut niemandem. Er jagt die {link:scourge}Geißel{/link}, doch er jagt auch die {link:forsaken}Verlassenen{/link}, und jeden Fremden behandelt er als möglichen Träger der Seuche.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nach dem {link:fall-of-lordaeron}Fall von Lordaeron{/link} lag der von {link:uther-the-lightbringer}Uther dem Lichtbringer{/link} gegründete Paladinorden zerschlagen, und viele seiner Ritter waren tot. Überlebende sammelten sich unter Großkreuzzügler Saidan Dathrohan, einem Paladin des alten Ordens. Sie schworen, {link:lordaeron}Lordaeron{/link} von jeder Spur der Seuche zu reinigen, und nahmen Scharlachrot als ihre Farbe an. Viele, die durch die {link:scourge}Geißel{/link} alles verloren hatten, strömten zu ihren Bannern.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Kreuzzug.{/b} Der Kreuzzug bekämpfte die {link:scourge}Geißel{/link} überall im Norden mit großem Mut und wenig Gnade. Er befestigte das Scharlachrote Kloster in {link:tirisfal-glades}Tirisfal{/link}, die Stadt {link:hearthglen}Hearthglen{/link} und die Stadt {link:tyr-s-hand}Tyrs Hand{/link}.
• {b}Die Eiferer.{/b} Mit der Zeit wandelte sich der Eifer des Kreuzzugs in Grausamkeit. Er begann, jeden zu säubern, den er der Seuche verdächtigte, und seine Inquisitoren wurden unter den Lebenden gefürchtet. Einige seiner Mitglieder konnten nicht ertragen, was aus ihm geworden war. Sie verließen ihn und gründeten die {link:argent-dawn}Argentumdämmerung{/link}.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Scharlachrote Kreuzzug hält das Kloster in {link:tirisfal-glades}Tirisfal{/link}, wo {link:high-inquisitor-whitemane}Hochinquisitorin Whitemane{/link} und der Scharlachrote Kommandant {link:scarlet-commander-mograine}Mograine{/link} seine Ritter anführen. Seine Streitkräfte halten auch {link:hearthglen}Hearthglen{/link} in den {link:western-plaguelands}Westlichen Pestländern{/link} und {link:tyr-s-hand}Tyrs Hand{/link} in den {link:eastern-plaguelands}Östlichen Pestländern{/link}. Seine Patrouillen verbrennen die Verlassenen, wo immer sie sie finden. Sein Eifer ist echt, und ebenso seine Stärke. Ob er dem Licht noch dient, ist eine Frage, die seine eigenen Mitglieder nicht mehr zu stellen wagen.]=],
		},
	},
})

Translate("deDE", "argent-dawn", {
	title = "Argentumdämmerung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Argentumdämmerung ist ein Orden, der geschworen hat, {link:azeroth}Azeroth{/link} gegen die {link:scourge}Geißel{/link}, die {link:burning-legion}Brennende Legion{/link} und jede andere Macht zu verteidigen, die es vernichten will. Sie steht abseits von Königen und Kriegshäuptlingen. Sie heißt jeden willkommen, der gegen die Untoten kämpfen will, gleich welchen Volkes oder Banners, und so zählt sie {link:orcs}Orcs{/link}, {link:humans}Menschen{/link}, {link:dwarves}Zwerge{/link} und sogar {link:forsaken}Verlassene{/link} zu ihren Freunden.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Dämmerung ging aus dem {link:scarlet-crusade}Scharlachroten Kreuzzug{/link} hervor. Als der Kreuzzug fanatisch wurde, begannen einige seiner Mitglieder zu fürchten, dass seine Anführer vom Weg abgekommen waren. {link:lord-maxwell-tyrosus}Lord Maxwell Tyrosus{/link} und andere weigerten sich, ihm weiter zu folgen. Sie verließen den Kreuzzug und gründeten einen neuen Orden, treu den Lehren des {link:holy-light}Heiligen Lichts{/link}, wie sie sie verstanden. Sein erster Anführer war Lord Raymond George.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Kampf im Norden.{/b} Von ihren ersten Tagen an bekämpfte die Argentumdämmerung die {link:scourge}Geißel{/link} überall in den Pestländern, oft mit wenigen Soldaten und noch weniger Vorräten.
• {b}Ein Orden, offen für alle.{/b} Anders als der Kreuzzug fragt die Dämmerung nicht, wer ihre Verbündeten im Leben waren. Sie nimmt die Hilfe der {link:alliance}Allianz{/link} und der {link:horde}Horde{/link} gleichermaßen an und beurteilt jeden allein nach seinen Taten.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:lord-maxwell-tyrosus}Lord Maxwell Tyrosus{/link} führt die Argentumdämmerung von der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} in den {link:eastern-plaguelands}Östlichen Pestländern{/link} aus. Ihre Lager sind über die Pestländer verstreut, und ihre Gesandten warten in fernen Städten, um Verbündete zu sammeln. Die Dämmerung belohnt jene, die Beweise für die Toten bringen, die sie vernichtet haben. Ihre Mitglieder sagen, dass der Krieg gegen die {link:scourge}Geißel{/link} von keiner Nation allein gewonnen werden wird.]=],
		},
	},
})

Translate("deDE", "defias-brotherhood", {
	title = "Bruderschaft der Defias",
	aliases = { "Defias" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Bruderschaft der Defias ist ein Heer von Gesetzlosen, das {link:westfall}Westfall{/link} an sich gerissen hat und die Lande des {link:kingdom-of-stormwind}Königreichs Stormwind{/link} heimsucht. Ihre Mitglieder tragen rote Halstücher und schlagen aus dem Schatten zu. In ihrem Kern stehen die Steinmetze, die {link:stormwind-city}Stormwind{/link} wieder aufbauten und nie für ihre Arbeit bezahlt wurden. Sie wollen sich nehmen, was man ihnen schuldet, und dann die Stadt selbst.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nach dem {link:second-war}Zweiten Krieg{/link} baute die {link:stonemasons-guild}Steinmetzgilde{/link} von {link:edwin-vancleef}Edwin VanCleef{/link} {link:stormwind-city}Stormwind{/link} aus seiner Asche wieder auf. Als ihre Arbeit getan war, weigerte sich das {link:house-of-nobles}Adelshaus{/link}, sie zu bezahlen. Die Steinmetze begehrten auf, und im Chaos wurde Königin {link:tiffin-wrynn}Tiffin Wrynn{/link} getötet. Die Steinmetze wurden aus der Stadt vertrieben. Unter VanCleefs Führung zogen sie nach Westen in {link:razorfen-downs}die Hügel{/link} und Felder von {link:westfall}Westfall{/link}, und dort wurden sie zur Bruderschaft der Defias.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Eroberung von {link:westfall}Westfall{/link}.{/b} Da das Heer fern und die Krone stumm war, nahm die Bruderschaft Westfall fast ohne Widerstand ein. Ihre Mitglieder vertrieben die Bauern von ihrem Land und machten das Dorf {link:moonbrook}Moonbrook{/link} zu ihrer Festung.
• {b}Der lange Arm der Bruderschaft.{/b} Diebe der Defias breiteten sich nach {link:elwynn-forest}Elwynn{/link}, ins {link:redridge-mountains}Rotkammgebirge{/link} und in den {link:duskwood}Dämmerwald{/link} aus. Gold, das {link:kobolds}Kobolde{/link} stehlen, gelangt zu ihren Agenten, und ihre Ringe tragen das alte Zeichen der {link:stonemasons-guild}Steinmetzgilde{/link}.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Bruderschaft beherrscht {link:westfall}Westfall{/link} aus dem Schatten. Unter {link:moonbrook}Moonbrook{/link}, in den {link:the-deadmines}Todesminen{/link}, bauen VanCleefs Steinmetze ein großes Schiff für einen Zweck, den sie geheim halten. Ihre {link:harvest-golems}Erntegolems{/link} bearbeiten gestohlene Felder, und ihre Banden halten die Straßen. Nur die Volksmiliz der {link:sentinel-hill}Späherkuppe{/link} unter {link:gryan-stoutmantle}Gryan Stoutmantle{/link} stellt sich ihnen entgegen. In Stormwinds Gefängnis, dem {link:the-stockade}Verlies{/link}, haben sich gefangene Defias erhoben und die Zellen für sich eingenommen.]=],
		},
	},
})

Translate("deDE", "stonemasons-guild", {
	title = "Steinmetzgilde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Steinmetzgilde war die Bruderschaft der Baumeister, die {link:stormwind-city}Stormwind{/link} nach dem Zweiten Krieg neu errichteten. Ihr Können gab der Stadt ihre weißen Mauern und großen Türme. Der Verrat des Königreichs an ihnen machte seine Steinmetzmeister zu seinen gefährlichsten Feinden.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als die Verbannten aus {link:stormwind-city}Stormwind{/link} aus {link:lordaeron}Lordaeron{/link} zurückkehrten, fanden sie ihre {link:capital-city}Hauptstadt{/link} in Ruinen. Die Arbeit des Wiederaufbaus fiel den Steinmetzen zu. Ihr Meister, {link:edwin-vancleef}Edwin VanCleef{/link}, war ein Handwerker von seltener Begabung, und unter ihm vollbrachte die Gilde in Jahren, was Generationen hätte dauern können. Die Stadt, wie sie heute steht, ist größtenteils ihr Werk.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Verrat.{/b} Als die Arbeit getan war, weigerte sich das {link:house-of-nobles}Adelshaus{/link}, den Steinmetzen zu zahlen, was man ihnen schuldete. Die Steinmetze protestierten, und der Protest wurde zum Aufruhr. Königin {link:tiffin-wrynn}Tiffin Wrynn{/link} wurde im Chaos getötet.
• {b}Das Exil.{/b} Die Steinmetze wurden aus {link:stormwind-city}Stormwind{/link} vertrieben. {link:edwin-vancleef}VanCleef{/link} führte sie nach Westen, wo sie zur {link:defias-brotherhood}Bruderschaft der Defias{/link} wurden. Die Fertigkeiten, die eine Stadt erbaut hatten, dienten nun dazu, Festungen für Diebe zu errichten.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Das Zeichen der alten Gilde überdauert auf den Ringen der {link:defias-brotherhood}Defias{/link} und im Mauerwerk der {link:the-deadmines}Todesminen{/link}. In {link:elwynn-forest}Elwynn{/link} und {link:westfall}Westfall{/link} bauen die Steinmetze nun für die Bruderschaft. Stormwinds Mauern stehen noch immer als bester Beweis dafür, was die Gilde vermochte.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik erzählt, was aus den Steinmetzen wurde, die {link:edwin-vancleef}VanCleef{/link} nicht ins Exil folgten, oder ob heute noch eine Steinmetzgilde in {link:stormwind-city}Stormwind{/link} arbeitet.]=],
		},
	},
})

Translate("deDE", "house-of-nobles", {
	title = "Adelshaus",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Adelshaus ist die Versammlung der großen Lords von {link:stormwind-city}Stormwind{/link}. Seine Mitglieder besitzen Land, Reichtum und alte Titel, und sie hatten lange die Hand im Spiel bei der Schatzkammer und den Gesetzen des Königreichs. Ihre Weigerung, die Steinmetze zu bezahlen, führte das Königreich auf den Weg zu seinen heutigen Nöten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann das Adelshaus zum ersten Mal zusammentrat. Es ist so alt wie die Adelsfamilien des Königreichs, und es hat Feuer und Exil überdauert. Als {link:stormwind-city}Stormwind{/link} nach dem {link:second-war}Zweiten Krieg{/link} wieder aufgebaut wurde, stand das Haus an der Seite des jungen Königs {link:varian-wrynn}Varian Wrynn{/link}, und seine Stimme hatte großes Gewicht am neuen Hof.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Lohn der Steinmetze.{/b} Die {link:stonemasons-guild}Steinmetzgilde{/link} baute die {link:capital-city}Hauptstadt{/link} unter {link:edwin-vancleef}Edwin VanCleef{/link} wieder auf. Als die Arbeit getan war, weigerte sich das Adelshaus, den Steinmetzen zu zahlen, was man ihnen schuldete. Der Protest der Steinmetze wurde zum Aufruhr, und Königin {link:tiffin-wrynn}Tiffin Wrynn{/link} starb in der Gewalt. Die Steinmetze wurden verbannt und wurden zur {link:defias-brotherhood}Bruderschaft der Defias{/link}.
• {b}Die Schuld.{/b} Viele in {link:stormwind-city}Stormwind{/link} geben noch immer den Adligen die Schuld am Tod der Königin und an den Defias. Die Adligen ihrerseits geben den Steinmetzen die Schuld.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Da {link:varian-wrynn}König Varian{/link} fort ist, haben die Adligen großen Einfluss auf die Regentschaft von Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link}. Lady {link:katrana-prestor}Katrana Prestor{/link} ist zu ihrem Liebling geworden, und ihr Rat wird in jeder Debatte gehört. Das einfache Volk murrt, dass die Lords über Steuern streiten, während {link:westfall}Westfall{/link} brennt. Der Regent muss die Adligen zufriedenstellen, und das macht seine Aufgabe nicht leichter.]=],
		},
	},
})

Translate("deDE", "si-7", {
	title = "SI:7",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[SI:7 ist der Geheimdienst des {link:kingdom-of-stormwind}Königreichs Stormwind{/link}. Seine Agenten sind Spione, Späher und Meuchelmörder, die der Krone im Stillen dienen. Sie beobachten die Feinde des Königreichs, außerhalb seiner Mauern wie innerhalb. Nur wenige in {link:stormwind-city}Stormwind{/link} wissen viel über sie, und so ist es ihnen am liebsten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann SI:7 gegründet wurde oder wer ihm zuerst seinen Namen gab. Es dient den Königen von {link:stormwind-city}Stormwind{/link} seit der Zeit vor dem {link:third-war}Dritten Krieg{/link}, und seine Agenten haben stets fern vom Licht des Hofes gearbeitet.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Im Schatten.{/b} SI:7 jagt seit vielen Jahren die verborgenen Feinde des Königreichs. Es hat rivalisierende Königreiche, Verräter in der Heimat und gefährliche Kulte beobachtet. Seine Mitglieder stammen vor allem aus den Schurken von {link:stormwind-city}Stormwind{/link}, die in seinem Hauptquartier ausgebildet werden.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:master-mathias-shaw}Meister Mathias Shaw{/link} führt SI:7 von seinem Hauptquartier in der Old Town von {link:stormwind-city}Stormwind{/link} aus. Seine Agenten verfolgen die {link:defias-brotherhood}Bruderschaft der Defias{/link} durch {link:westfall}Westfall{/link}, beobachten die Verbündeten der Bruderschaft und berichten über seltsame Vorgänge unter den {link:forsaken}Verlassenen{/link}. Einige dienen in {link:theramore-isle}Theramore{/link}, um die Herrschaft von {link:jaina-proudmoore}Jaina Proudmoore{/link} zu schützen. Andere haben sich den Schurken von {link:ravenholdt-manor}Ravenholdt{/link} im Krieg gegen das {link:syndicate}Syndikat{/link} angeschlossen. Da der König fort und das Heer in der Ferne ist, ist Shaws stille Arbeit wichtiger denn je.]=],
		},
	},
})

Translate("deDE", "explorers-league", {
	title = "Forscherliga",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Forscherliga ist eine Gesellschaft zwergischer Gelehrter und Abenteurer mit Sitz in {link:ironforge}Ironforge{/link}. Ihre Mitglieder graben nach Relikten, kartieren vergessene Ruinen und erforschen die Geheimnisse der alten Welt. Vor allem suchen sie den wahren Ursprung des {link:dwarves}Volkes der Zwerge{/link}, und sie glauben, dass die Antwort im Stein begraben liegt.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die {link:dwarves}Zwerge{/link} haben schon immer tief gegraben, doch die Liga machte aus dem Graben eine Wissenschaft. Von der {link:hall-of-explorers}Hall of Explorers{/link} in {link:ironforge}Ironforge{/link} aus sendet sie Expeditionen in die ganze Welt und sammelt, was diese finden. Ihre Mitglieder schätzen Wissen so hoch wie Gold. Sie sind für ihren Mut bekannt, und ebenso bekannt für ihre Missachtung der Gefahr.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die große Grabung.{/b} Die Liga glaubt seit Langem, dass die {link:dwarves}Zwerge{/link} von den Titanen, den Erschaffern der Welt, aus Stein geformt wurden. Ihre Expeditionen haben alte Ruinen in ganz Khaz Modan und darüber hinaus nach Beweisen dafür durchsucht.
• {b}Berühmte Namen.{/b} Zu ihren Mitgliedern gehört {link:brann-bronzebeard}Brann Bronzebeard{/link}, Bruder von König {link:magni-bronzebeard}Magni Bronzebeard{/link}, der berühmteste Forscher seiner Zeit.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Hochforscher {link:high-explorer-magellas}Magellas{/link} führt die Liga von der {link:hall-of-explorers}Hall of Explorers{/link} aus. Ihre Grabungsstätten sind über die ganze Welt verstreut: in {link:ironband-s-excavation-site}Ironbands Ausgrabungsstätte{/link} in {link:loch-modan}Loch Modan{/link}, in {link:bael-modan}Bael Modan{/link} im {link:the-barrens}Brachland{/link} und in den Ruinen von {link:uldaman}Uldaman{/link} im {link:badlands}Ödland{/link}. Im {link:wetlands}Sumpfland{/link} hat {link:whelgar-s-excavation-site}Whelgars Ausgrabungsstätte{/link} etwas freigelegt, worauf ihre Gräber nicht vorbereitet waren. Angriffe der {link:troggs}Troggs{/link} und rivalisierende Ansprüche plagen viele dieser Stätten, doch die Liga gibt nicht leicht auf.]=],
		},
	},
})

Translate("deDE", "cenarion-circle", {
	title = "Zirkel des Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Zirkel des Cenarius ist der Orden der Druiden, der Hüter der Natur. Seine Mitglieder schöpfen ihre Macht aus dem Land und aus dem {link:emerald-dream}Smaragdgrünen Traum{/link}, und sie haben geschworen, die lebendige Welt zu schützen. Der Zirkel ist nach dem Halbgott {link:cenarius}Cenarius{/link} benannt. Lange ein Orden der {link:night-elves}Nachtelfen{/link}, zählt er nun auch {link:tauren}Tauren{/link} zu seinen Mitgliedern.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Der erste Druide der {link:night-elves}Nachtelfen{/link} war {link:malfurion-stormrage}Malfurion Stormrage{/link}, der von {link:cenarius}Cenarius{/link} selbst unterwiesen wurde. Im {link:war-of-the-ancients}Krieg der Ahnen{/link} setzten Malfurion und seine Anhänger ihre neue Kunst gegen die {link:burning-legion}Brennende Legion{/link} ein. Nach der {link:great-sundering}Großen Teilung{/link} wurden die Druiden zu Hütern der Lande der Nachtelfen. Tausende Jahre lang schliefen sie im Smaragdgrünen Traum und erwachten nur in Zeiten der Not.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Dritte Krieg.{/b} Die Druiden wurden geweckt, um sich der Legion erneut zu stellen. Sie kämpften in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link}, wo der Weltbaum {link:nordrassil}Nordrassil{/link} geopfert wurde, um {link:archimonde}Archimonde{/link} zu vernichten.
• {b}Ein offener Zirkel.{/b} In den Jahren seither hat der Zirkel Druiden der {link:tauren}Tauren{/link} aufgenommen, als ersten unter ihnen {link:hamuul-runetotem}Hamuul Runetotem{/link}. Er steht abseits von {link:alliance}Allianz{/link} und {link:horde}Horde{/link}.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Das Herz des Zirkels ist {link:moonglade}Moonglade{/link}, ein heiliges Tal, in dem {link:keeper-remulos}Bewahrer Remulos{/link}, Sohn des {link:cenarius}Cenarius{/link}, Wache hält. Seine Druiden pflegen die wilden Orte von {link:kalimdor}Kalimdor{/link} und versuchen, die Verderbnis des {link:felwood}Teufelswalds{/link} zu heilen. {link:malfurion-stormrage}Malfurion{/link} hat sich in den Smaragdgrünen Traum zurückgezogen. In seiner Abwesenheit führt Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} die Druiden von {link:darnassus}Darnassus{/link}, wo ein neuer Weltbaum, {link:teldrassil}Teldrassil{/link}, gewachsen ist.]=],
		},
	},
})

Translate("deDE", "earthen-ring", {
	title = "Irdener Ring",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Irdene Ring ist ein Rat von Schamanen, der sich dem Gleichgewicht der {link:elements}Elemente{/link} verschrieben hat. Seine Mitglieder lauschen den Geistern der Erde, des Feuers, des Wassers und der Luft, und sie bemühen sich, diese Kräfte im Einklang zu halten. Der Ring steht über den Streitigkeiten der Nationen. Sein Blick gilt der Welt selbst.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Der Irdene Ring wurde vor langer Zeit von den {link:tauren}Tauren{/link} gegründet, um ihr Volk mit Weisheit zu leiten und den Frieden zwischen den Elementargeistern zu wahren. Seine Ältesten treten seit Generationen zu Rat zusammen. Die Schamanen des Rings befehlen den Elementen nicht. Sie bitten, sie verhandeln, und sie vergessen nicht, dass die Geister keine Diener sind.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die neuen Schamanen.{/b} Als {link:thrall}Thrall{/link} die {link:orcs}Orcs{/link} zu den Wegen der Schamanen zurückführte, trafen sich die Pfade der {link:tauren}Tauren{/link} und der Orcs. Nach dem {link:third-war}Dritten Krieg{/link} begann der Irdene Ring, Schamanen der Orcs und {link:trolls}Trolle{/link} in seine Kreise aufzunehmen.
• {b}Die Verlassenen.{/b} Als die {link:forsaken}Verlassenen{/link} darum baten, der {link:horde}Horde{/link} beizutreten, gaben sie an, in den heilenden Kräften der Erde ein Heilmittel für ihren Untod zu suchen. Thrall und {link:cairne-bloodhoof}Cairne Bloodhoof{/link} waren misstrauisch. Es war der Ältestenrat des Rings, der die Horde drängte, ihnen zu helfen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Schamanen des Irdenen Rings wachen über die {link:elements}Elemente{/link} von {link:kalimdor}Kalimdor{/link} und darüber hinaus. Was sie hören, beunruhigt sie. In den Tiefen des {link:blackrock-mountain}Blackrock{/link} tobt Feuer, und in vielen Landen werden die Elemente unruhig. {link:muln-earthfury}Muln Earthfury{/link}, ein Taure von großer Weisheit, führt den Ring, auch wenn er sich selten zeigt.]=],
		},
	},
})

Translate("deDE", "twilight-s-hammer", {
	title = "Schattenhammer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schattenhammer ist ein Kult des Untergangs. Einst war er ein Clan der {link:orcs}Orcs{/link} in der {link:horde}Horde{/link}. Nun ist er eine Gemeinschaft von Wahnsinnigen aller Völker, die uralte, unter der Welt begrabene Mächte verehren und sich nach dem Ende aller Dinge sehnen. Wo der Kult sich versammelt, werden im Dunkeln seltsame Riten abgehalten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Der Schattenhammer war ein Clan der {link:horde}Horde{/link}, angeführt von Cho'gall, einem zweiköpfigen Ogermagier, der zu den engsten Dienern von {link:gul-dan}Gul'dan{/link} gehörte. Selbst unter den {link:orcs}Orcs{/link} waren seine Mitglieder als Fanatiker gefürchtet. Sie glaubten, dass die Welt dem Untergang geweiht sei und dass es ihre Aufgabe sei, ihr Ende zu beschleunigen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Zweite Krieg.{/b} Mitten im {link:second-war}Zweiten Krieg{/link} verriet {link:gul-dan}Gul'dan{/link} die {link:horde}Horde{/link}, um das {link:the-sepulcher}Grabmal{/link} des {link:sargeras}Sargeras{/link} zu suchen. Cho'gall und sein Clan folgten ihm. Kriegshäuptling {link:orgrim-doomhammer}Orgrim Doomhammer{/link} wandte seine Heere gegen die Verräter und zerschlug den Clan, und die {link:alliance}Allianz{/link} nutzte das Chaos aus. Keine Chronik dieses Zeitalters verzeichnet Cho'galls Schicksal.
• {b}Der wiedergeborene Kult.{/b} Der Clan starb nicht. Er wurde zu einem Kult, der den Alten Göttern ergeben ist, den dunklen Mächten, die tief in {link:azeroth}Azeroth{/link} gefangen sind. Er begann, Angehörige vieler Völker anzuziehen, die seinen Hunger nach Verderben teilten.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Kult wirkt an verborgenen Orten. Seine Mitglieder wurden in den überfluteten Ruinen der {link:blackfathom-deeps}Blackfathom-Tiefe{/link} im {link:ashenvale}Eschental{/link} gefunden, wo sie unter den {link:naga}Naga{/link} dunkle Riten vollziehen. Man sagt, seine Lager lägen in der Wüste von {link:silithus}Silithus{/link}, weit im Süden. Niemand weiß, wie viele dem Hammer dienen oder wie nahe seine Mitglieder den Thronen der Welt stehen.]=],
		},
	},
})

Translate("deDE", "burning-blade", {
	title = "Brennende Klinge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Brennende Klinge war einst ein Clan der {link:orcs}Orcs{/link}, bekannt für seine gefürchteten Schwertkämpfer. Nun ist sie vor allem ein Kult von Dämonenanbetern, der sich unter den Orcs der neuen {link:horde}Horde{/link} verbirgt. Ihre Mitglieder dienen der {link:burning-legion}Brennenden Legion{/link} und arbeiten daran, ihr Volk in die Verderbnis zurückzuziehen, aus der {link:thrall}Thrall{/link} es befreit hat.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Auf Draenor war die Brennende Klinge ein Clan der {link:orcs}Orcs{/link}, berühmt für seine Klingenmeister. Als die Orcs der Macht der Dämonen verfielen, fiel die Brennende Klinge tiefer als die meisten. Im {link:first-war}Ersten Krieg{/link} und im {link:second-war}Zweiten Krieg{/link} waren ihre Krieger eine chaotische Bruderschaft, wahnsinnig vor Kampfeslust und niemandem treu. Man ließ sie nur in Zeiten großer Not auf den Feind los.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Zwei Wege.{/b} Nach dem Zweiten Krieg schlossen sich einige Klingenmeister des Clans Thralls neuer {link:horde}Horde{/link} an und schworen, sich von der Herrschaft der Dämonen zu befreien. Andere blieben den Dämonen treu. Unter dem {link:shadow-council}Schattenrat{/link}, den letzten Hexenmeistern der {link:orcs}Orcs{/link}, wurden diese zu einem geheimen Kult.
• {b}Der Kult breitet sich aus.{/b} Der Kult hat Angehörige anderer Völker aufgenommen, sogar {link:humans}Menschen{/link} und {link:forsaken}Verlassene{/link}, die seine Ergebenheit gegenüber der Legion teilen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Brennende Klinge schwärt in {link:durotar}Durotar{/link} und im {link:the-barrens}Brachland{/link}. Ihre Kultisten verbergen sich in den Höhlen von Durotar, in der Knochenhöhle und in der Staubwindhöhle, und sie schmieden Pläne unter {link:orgrimmar}Orgrimmar{/link} selbst. In {link:desolace}Desolace{/link} halten sie die {link:thunder-axe-fortress}Festung Thunder Axe{/link}, wo ihre dämonischen Herren frei umhergehen. Die Krieger der {link:horde}Horde{/link} jagen sie ohne Rast, doch der Kult scheint stets neue Anhänger zu finden.]=],
		},
	},
})

Translate("deDE", "dark-iron-dwarves", {
	title = "Dunkeleisenzwerge",
	aliases = { "Dunkeleisenclan", "Dunkeleisen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dunkeleisenzwerge sind die gefürchtetsten der drei Zwergenclans. Sie sind Meister des Feuers und der dunklen Magie. Vor zwei Jahrhunderten führten sie Krieg gegen ihre Verwandten, und in ihrer Niederlage entfesselten sie einen Herrn der Flammen, der sie versklavte. Sie leben nun in den Tiefen des {link:blackrock-mountain}Blackrock{/link}, gebunden an den Dienst des Feuerfürsten Ragnaros.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Vor langer Zeit waren die {link:dwarves}Zwerge{/link} von Khaz Modan ein Volk, beherrscht von {link:ironforge}Ironforge{/link} aus durch den Hochkönig Modimus Anvilmar. Als Modimus starb, kämpften drei Clans um den Thron: die Bronzebeards, die Wildhammers und die Dunkeleisen des Zauberer-Thanes {link:ruins-of-thaurissan}Thaurissan{/link}. Die Bronzebeards siegten und vertrieben die anderen. Die Dunkeleisen zogen nach Süden und erbauten die Stadt Thaurissan in den Bergen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Krieg der drei Hämmer.{/b} Etwa zweihundertdreißig Jahre vor dem Dunklen Portal griffen die Dunkeleisen sowohl {link:ironforge}Ironforge{/link} als auch {link:grim-batol}Grim Batol{/link}, den Sitz der Wildhammers, an. Sie wurden vor den Toren von Ironforge besiegt.
• {b}Die Ankunft von Ragnaros.{/b} In seiner Verzweiflung suchte {link:ruins-of-thaurissan}Thaurissan{/link} eine große Macht, die ihm helfen sollte. Er beschwor Ragnaros, den Herrn der Feuerelementare. Die Ankunft des Feuerfürsten riss das Land auseinander und schuf die {link:searing-gorge}Sengende Schlucht{/link} und die {link:burning-steppes}Brennende Steppe{/link}. {link:blackrock-mountain}Der Blackrock{/link} erhob sich dort, wo die Stadt gestanden hatte, und die Dunkeleisen wurden zu Sklaven von Ragnaros.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Imperator Dagran {link:ruins-of-thaurissan}Thaurissan{/link} beherrscht die Dunkeleisen von Shadowforge City aus, tief im Inneren des {link:blackrock-mountain}Blackrock{/link}. Ragnaros beherrscht sie alle vom geschmolzenen Kern darunter. Streitkräfte der Dunkeleisen plündern die {link:searing-gorge}Sengende Schlucht{/link}, graben im {link:badlands}Ödland{/link} und bedrohen das {link:wetlands}Sumpfland{/link}. König {link:magni-bronzebeard}Magni Bronzebeard{/link} behauptet, seine Tochter Moira sei vom Imperator entführt worden, und er will sie zurück.]=],
		},
	},
})

Translate("deDE", "steamwheedle-cartel", {
	title = "Steamwheedle-Kartell",
	aliases = { "Steamwheedle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Steamwheedle-Kartell ist die größte der Handelsgesellschaften der Goblins. Es besitzt Häfen und Städte auf beiden Seiten des Meeres und hält sie für jeden Kunden mit Gold offen. Das Kartell kennt nur eine Treue: den Profit. Seine Neutralität hat es reich gemacht, und es schützt diese Neutralität mit angeheuerten Schlägern.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Goblins dienten der alten {link:horde}Horde{/link} im {link:second-war}Zweiten Krieg{/link}. Der Handelsprinz des Kartells verkaufte den {link:orcs}Orcs{/link} Maschinen, Karten, Alchemie und Zeppeline, und er baute Schiffe für Doomhammers Flotte. Als die Horde besiegt wurde, lernten die Goblins eine Lektion. Es zahlte sich besser aus, an beide Seiten zu verkaufen, als für eine davon Partei zu ergreifen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}{link:booty-bay}Booty Bay{/link}.{/b} Vor dem {link:first-war}Ersten Krieg{/link} vertrieben die Goblins des Kartells die {link:trolls}Trolle{/link} aus einem kleinen Hafen an der Südspitze des Schlingendorntals. Sie machten ihn zu ihrem Hafen Booty Bay.
• {b}Jenseits des Meeres.{/b} In den folgenden Jahren baute oder beanspruchte das Kartell Städte überall in {link:kalimdor}Kalimdor{/link}: {link:ratchet}Ratchet{/link} an der Küste des {link:the-barrens}Brachlands{/link}, {link:gadgetzan}Gadgetzan{/link} in der Wüste von {link:tanaris}Tanaris{/link} und {link:everlook}Everlook{/link} im gefrorenen Norden von {link:winterspring}Winterspring{/link}.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Städte des Kartells sind Zufluchtsorte, an denen {link:orcs}Orc{/link} und Mensch handeln können, ohne die Klingen zu ziehen. Ihre Schläger wahren den Frieden mit harter Hand. {link:baron-revilgaz}Baron Revilgaz{/link} herrscht über {link:booty-bay}Booty Bay{/link}, {link:gazlowe}Gazlowe{/link} wacht über {link:ratchet}Ratchet{/link}, und Bürgermeister {link:marin-noggenfogger}Noggenfogger{/link} regiert {link:gadgetzan}Gadgetzan{/link}. Jede Stadt kämpft mit Piraten, rivalisierenden Gesellschaften und dem wilden Land um sie herum. Viele ihrer Nöte gehen von der {link:venture-company}Venture Co.{/link} aus, einem Goblinkartell ohne jede ihrer Umgangsformen.]=],
		},
	},
})

Translate("deDE", "venture-company", {
	title = "Venture Co.",
	aliases = { "Venture Company" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Venture Co. ist ein Goblinkartell, das die Welt ihrer Reichtümer beraubt. Wenn sich etwas abbauen, fällen oder aus dem Boden pumpen lässt, nimmt die Venture Co. es sich, und es kümmert sie nicht, wer zuerst dort lebte. Ihre Schredder und Bohrer hinterlassen vergiftete Seen und kahle Hügel.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet die Gründung der Venture Co. Sie ist eines der Goblinkartelle von Undermine und wird seit vielen Jahren von ihrem Präsidenten, Mogul Razdunk, geführt. Anders als das {link:steamwheedle-cartel}Steamwheedle-Kartell{/link} unterhält sie keine neutralen Städte und gibt nicht vor, Ehre zu besitzen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}In Kalimdor.{/b} Die Gesellschaft kam nach dem {link:third-war}Dritten Krieg{/link} nach {link:kalimdor}Kalimdor{/link} und begann, es auszuplündern. Sie pumpte Öl im {link:the-sludge-fen}Schlickermoor{/link} des {link:the-barrens}Brachlands{/link}. Sie fällte die Wälder des {link:stonetalon-mountains}Steinkrallengebirges{/link}, und sie grub sich in die Klippen von {link:mulgore}Mulgore{/link}, nachdem die {link:tauren}Tauren{/link} ihr das Recht dazu verweigert hatten.
• {b}In den Östlichen Königreichen.{/b} Im {link:stranglethorn-vale}Schlingendorntal{/link} rodete die Gesellschaft den Dschungel für Holz und grub nach seltenen Kristallen. Sie hat auch dunkle Geheimnisse an die {link:defias-brotherhood}Bruderschaft der Defias{/link} verkauft.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Venture Co. ist überall auf der Welt am Werk. Sie verschmutzt die {link:water-wells-of-mulgore}Brunnen von Mulgore{/link} und reißt mit großen Maschinen an den Wäldern des Steinkrallengebirges. Die {link:tauren}Tauren{/link}, die {link:night-elves}Nachtelfen{/link} und die Goblins von {link:steamwheedle-port}Steamwheedle{/link} zählen sie alle zu ihren Feinden. Ihre Aufseher kümmert das nicht, solange das Erz weiter fließt.]=],
		},
	},
})

Translate("deDE", "syndicate", {
	title = "Syndikat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Syndikat ist ein verbrecherischer Bund der gefallenen Adligen von {link:alterac-mountains}Alterac{/link}. Es besteht aus Dieben, Meuchelmördern und Räubern, die Lords ohne Königreich dienen. Seine Mitglieder suchen das Alteracgebirge, das {link:hillsbrad-foothills}Vorgebirge von Hillsbrad{/link} und das {link:arathi-highlands}Arathihochland{/link} heim, und sie träumen von einer Krone, die man ihnen genommen hat.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Im {link:second-war}Zweiten Krieg{/link} verriet {link:aiden-perenolde}Lord Aiden Perenolde{/link}, König von {link:alterac-mountains}Alterac{/link}, die {link:alliance}Allianz von Lordaeron{/link} an die {link:horde}Horde{/link}. Als der Krieg vorüber war, wurden Alterac seine Krone und seine Lande genommen. Die Adligen von Alterac verziehen den anderen Königreichen nie. Angeführt von Perenoldes Erben, {link:lord-aliden-perenolde}Lord Aliden Perenolde{/link}, sammelten sie Diebe und Söldner und machten daraus das Syndikat.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Vor dem Dritten Krieg.{/b} Banditen des Syndikats waren bereits in den Wäldern von {link:alterac-mountains}Alterac{/link} am Werk, bevor die Seuche {link:lordaeron}Lordaeron{/link} traf.
• {b}Nach dem Fall.{/b} Als Lordaeron fiel, breitete sich das Syndikat in den Ruinen aus, die es hinterließ. Es nahm {link:durnholde-keep}Burg Durnholde{/link} im {link:hillsbrad-foothills}Vorgebirge von Hillsbrad{/link} und einen Großteil von {link:stromgarde-keep}Stromgarde{/link} im {link:arathi-highlands}Arathihochland{/link} ein.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:lord-aliden-perenolde}Aliden Perenolde{/link} lenkt das Syndikat von {link:dandred-s-fold}Dandreds Senke{/link} im {link:alterac-mountains}Alteracgebirge{/link} aus, und es hält die Stadt {link:strahnbrad}Strahnbrad{/link} als Festung. {link:lord-falconcrest}Lord Falconcrest{/link} befehligt seine Streitkräfte in den Ruinen von {link:stromgarde-keep}Stromgarde{/link}. Es stiehlt Pferde und Lieferungen aus {link:southshore}Southshore{/link} und überfällt die Soldaten von Stromgarde. Die Schurken von {link:ravenholdt-manor}Ravenholdt{/link} führen einen langen Krieg gegen es, und die {link:forsaken}Verlassenen{/link} haben auf den Kopf jedes seiner Mitglieder einen Preis ausgesetzt.]=],
		},
	},
})

Translate("deDE", "royal-apothecary-society", {
	title = "Königliche Apothekervereinigung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Königliche Apothekervereinigung ist der Orden der Alchemisten, die {link:sylvanas-windrunner}Sylvanas Windrunner{/link} dienen, der Bansheekönigin der {link:forsaken}Verlassenen{/link}. In den Gewölben unter der {link:undercity}Undercity{/link} brauen ihre Apotheker Gifte und Seuchen. Ihr erklärtes Ziel ist ein Heilmittel für den Untod. Ihr wahres Ziel ist finsterer.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Vereinigung wurde von {link:sylvanas-windrunner}Sylvanas{/link} gegründet, nachdem die Verlassenen ihre Freiheit von der {link:scourge}Geißel{/link} errungen hatten. Ihre Apotheker machten sich daran, zu tun, was kein lebender Alchemist wagte: die Seuche, die die Verlassenen geschaffen hatte, zu nehmen und in eine eigene Waffe zu verwandeln. Die Apotheker richteten ihre Laboratorien im Apothecarium ein, unter dem Royal Quarter der {link:undercity}Undercity{/link}.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Heilmittel und die Seuche.{/b} Als die Verlassenen der {link:horde}Horde{/link} beitraten, glaubten deren andere Völker, die Apotheker suchten ein Heilmittel für ihren Zustand. In Wahrheit war die erste Arbeit der Vereinigung eine neue Seuche, die die {link:scourge}Geißel{/link} vernichten sollte.
• {b}Andere Künste.{/b} Die Vereinigung hat auch tote Pferde erweckt, damit sie den Verlassenen als Reittiere dienen, und sie sendet ihre Mitglieder weit umher, um neue Zutaten zu sammeln.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Im Apothecarium überwacht {link:master-apothecary-faranell}Meisterapotheker Faranell{/link} die Arbeit an der neuen Seuche, und die Agenten der Vereinigung erproben sie auf den Feldern des {link:hillsbrad-foothills}Vorgebirges von Hillsbrad{/link} und anderswo. Ihre Apotheker dienen in jedem Außenposten der Verlassenen. Ihre Verbündeten in der {link:horde}Horde{/link} beobachten sie mit wachsendem Unbehagen.]=],
		},
	},
})

Translate("deDE", "darkspear-trolls", {
	title = "Darkspear",
	aliases = { "Stamm der Darkspear", "Trolle der Darkspear" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Darkspear sind ein Stamm von {link:trolls}Dschungeltrollen{/link}, der zur {link:horde}Horde{/link} steht. Sie waren Ausgestoßene und Wanderer, bis {link:thrall}Thrall{/link} sie vor der Vernichtung rettete. Nun sind sie die treuesten Verbündeten der {link:orcs}Orcs{/link}. Sie sind Jäger, Hexendoktoren und wilde Krieger, und sie verdanken ihr Überleben dem Kriegshäuptling.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Darkspear waren einst ein Stamm der Gurubashi, der Dschungeltrolle des Schlingendorntals. Als das Imperium der Gurubashi zerfiel, wandten sich seine Stämme gegeneinander, und die Darkspear wurden vertrieben. Sie schufen sich eine neue Heimat auf Inseln in den südlichen Meeren.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Rettung.{/b} Als Thralls Flotte von einem Sturm auf ihre Insel getrieben wurde, schwebten die Darkspear in großer Gefahr. {link:humans}Menschen{/link} aus {link:kul-tiras}Kul Tiras{/link} und {link:murlocs}Murlocs{/link} aus dem Meer griffen sie an. {link:thrall}Thrall{/link} kämpfte an ihrer Seite, und ihr Anführer {link:sen-jin-village}Sen'jin{/link} wurde gefangen genommen. Sen'jin starb als Gefangener der Murlocs, doch er hatte vorhergesehen, dass Thrall sein Volk in eine neue Heimat führen würde.
• {b}Kalimdor.{/b} Die Darkspear segelten mit der {link:horde}Horde{/link} nach {link:kalimdor}Kalimdor{/link} und ließen sich auf den Echoinseln vor der Küste von {link:durotar}Durotar{/link} nieder.
• {b}{link:zalazane}Zalazane{/link}.{/b} Ein Hexendoktor namens Zalazane wandte sich gegen seinen Stamm. Mit dunklem Voodoo versklavte er viele der {link:trolls}Trolle{/link} der Echoinseln und vertrieb die übrigen aus ihrer Heimat.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die freien Darkspear haben sich an der Küste von {link:durotar}Durotar{/link} niedergelassen, in dem Dorf, das sie nach {link:sen-jin-village}Sen'jin{/link} benannt haben. Sen'jins Sohn {link:vol-jin}Vol'jin{/link} führt sie und steht in {link:orgrimmar}Orgrimmar{/link} an Thralls Seite. {link:zalazane}Zalazane{/link} herrscht noch über die Echoinseln, und die Darkspear wollen sie zurückerobern.]=],
		},
	},
})

Translate("deDE", "kingdom-of-ironforge", {
	title = "Königreich Ironforge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Königreich Ironforge ist das Reich der {link:dwarves}Zwerge{/link} vom Clan Bronzebeard. Seine {link:capital-city}Hauptstadt{/link} ist ins Herz eines Berges in {link:dun-morogh}Dun Morogh{/link} gehauen, und seine Schmieden brennen seit Tausenden von Jahren. Es ist ein Königreich von Bergleuten, Schmieden, Ingenieuren und Gelehrten. Es ist auch eine der beiden Säulen der {link:alliance}Allianz{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die {link:dwarves}Zwerge{/link} sagen, sie seien in vergangenen Zeitaltern aus Stein geformt worden. Ihre älteste Stadt ist {link:ironforge}Ironforge{/link}, und lange Zeit wurden alle Zwerge von dort aus regiert. Als Hochkönig Modimus Anvilmar starb, kämpften die Clans Bronzebeard, Wildhammer und Dunkeleisen um den Thron. Die Bronzebeards hielten Ironforge und vertrieben die beiden anderen Clans. Im Krieg der drei Hämmer besiegten sie die {link:dark-iron-dwarves}Dunkeleisen{/link} vor den Toren der Stadt.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Freunde der {link:humans}Menschen{/link}.{/b} Forscher aus {link:arathor}Arathor{/link} erreichten Khaz Modan vor langer Zeit. {link:dwarves}Zwerge{/link} und Menschen wurden Freunde und tauschten Wissen über Schmiedekunst, Ingenieurskunst und Magie aus.
• {b}Der Zweite Krieg.{/b} Als die {link:horde}Horde{/link} Khaz Modan überrannte, hielt {link:ironforge}Ironforge{/link} selbst stand. Die Zwerge traten der {link:alliance}Allianz von Lordaeron{/link} bei, und sie vergaßen nicht, wer an ihrer Seite stand.
• {b}Der Dritte Krieg.{/b} König {link:magni-bronzebeard}Magni Bronzebeard{/link}s Bruder {link:muradin-bronzebeard}Muradin Bronzebeard{/link} zog mit Prinz {link:arthas-menethil}Arthas Menethil{/link} nach Nordend und kehrte nie zurück. Die Zwerge betrauern ihn als verloren.
• {b}Der Fall von Gnomeregan.{/b} Als {link:gnomeregan}Gnomeregan{/link} verloren ging, gab Magni den überlebenden {link:gnomes}Gnomen{/link} eine Heimat in seiner Stadt.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:magni-bronzebeard}König Magni{/link} herrscht über {link:ironforge}Ironforge{/link}. Sein jüngerer Bruder {link:brann-bronzebeard}Brann Bronzebeard{/link} durchstreift die Welt für die {link:explorers-league}Forscherliga{/link}. Die {link:gnomes}Gnome{/link} von {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} leben in {link:tinker-town}Tinker Town{/link}, im Herzen der Stadt. Zwergische Soldaten bewachen {link:loch-modan}Loch Modan{/link} und die Pässe des Südens. Die {link:dark-iron-dwarves}Dunkeleisen{/link} drohen vom {link:blackrock-mountain}Blackrock{/link} her, und Magni trauert um seine Tochter Moira, die, wie er sagt, von ihrem Imperator entführt wurde.]=],
		},
	},
})
